Could you check that each of the following requirements have their own separate line?    - every fact the policy says to extract, and the rules for missing, conflicting and corrected values;
   - each of the five review-queue rules, in the policy's order;
   - each processing and recovery rule: errors, retries, hashes, reruns, changed input, history;
   - each file `CHALLENGE.md` asks you to submit;
   - each case `docs/requirements.md` § Verification lists.

input.command:
python3 - <<'PY'
from pathlib import Path
import re

p = Path('planning/spec.md')
lines = p.read_text().splitlines()

def check(name, assertion):
    return f'Proposed `tests/test_acceptance.py::{name}`: {assertion}; command: `env -u API_KEY python3 -m unittest discover -s tests -p test_acceptance.py -k {name}`'

def row(requirement, source, verification):
    return [requirement, source, verification]

updated = []
count = 0
for line in lines:
    match = re.match(r'^\| R-(\d+) \|', line)
    if not match:
        updated.append(line)
        continue
    old = int(match.group(1))
    cells = line.split(' | ')
    requirement, source, verification = cells[1], cells[2], cells[3].removesuffix(' |')
    replacements = [row(requirement, source, verification)]
    if old == 27:
        replacements = [
            row('Each absent scalar fact shall be null with an explanatory issue.', source, check('test_missing_facts', 'assert null and a fact-specific issue for a missing manager and missing end date')),
            row('Each unresolved scalar fact shall be null with an explanatory issue.', source, check('test_unresolved_facts', 'assert null and a fact-specific issue for conflicting managers, conflicting environments and relative dates')),
        ]
    elif old == 44:
        replacements = [
            row("A slow response for one message shall leave other messages' work available.", source, check('test_slow_message_isolation', 'hold one response pending while another completes and remains inspectable')),
            row('An extraction failure shall allow unaffected messages to continue through intake.', '`materials/office-policy.md` § Processing and recovery — “Keep unaffected messages moving through intake.”', check('test_failed_message_isolation', 'fail one message while another completes and remains inspectable')),
        ]
    elif old == 48:
        replacements = [
            row('Changed input shall create a new result.', source, check('test_changed_source_new_result', 'revise a message and assert a new current result associated with the changed source hash')),
            row('When input changes, the earlier result shall be retained with its earlier source hash.', source, check('test_changed_source_retains_history', 'compare the retained earlier result and hash with the previously recorded version after processing changed input')),
        ]
    elif old == 50:
        replacements = [
            row('A later failed attempt shall preserve the last valid result in history.', source, check('test_failed_attempt_preserves_history', 'succeed then fail a later attempt and assert the earlier valid result remains in history')),
            row("The current queue shall show the latest attempt's error when a later extraction attempt fails.", source, check('test_failed_attempt_current_error', 'succeed then fail a later attempt and assert the current queue shows the latest error rather than the earlier success')),
        ]
    elif old == 67:
        replacements = [
            row('Credentials shall be kept in environment variables.', source, check('test_credentials_environment', 'inject a dummy environment credential and confirm configuration reads it without requiring a stored credential')),
            row('Operational logs shall redact credentials.', source, check('test_operational_log_redaction', 'use a distinctive dummy credential and assert that operational logs do not expose it')),
        ]
    elif old == 83:
        replacements = [
            row('The submission shall include runnable source, the extraction prompt, schema and model request configuration.', source, 'Inspect tracked application source, prompt, schema and model request configuration: locate each artifact and follow the documented setup/intake instructions to verify the application runs; command: `git ls-files`'),
            row('The submission shall include a dependency lockfile.', '`CHALLENGE.md` § What to submit / Source code and dependency lockfile — “Source code and dependency lockfile”', 'Inspect the tracked dependency lockfile: confirm it is included with the submitted application; command: `git ls-files`'),
        ]
    for requirement, source, verification in replacements:
        count += 1
        updated.append(f'| R-{count:02d} | {requirement} | {source} | {verification} |')
p.write_text('\n'.join(updated).rstrip() + '\n')
print(f'Updated {p}: {count} requirements; six combined rows split; IDs renumbered sequentially')
PY
